package org.junit.jupiter.api;

import org.opentest4j.AssertionFailedError;

public class AssertionFailureBuilder {
    public static AssertionFailureBuilder assertionFailure() { return new AssertionFailureBuilder(); }
    public AssertionFailureBuilder message(Object m) { return this; }
    public AssertionFailureBuilder reason(String r) { return this; }
    public AssertionFailureBuilder cause(Throwable c) { return this; }
    public AssertionFailureBuilder expected(Object e) { return this; }
    public AssertionFailureBuilder actual(Object a) { return this; }
    public AssertionFailureBuilder includeValuesInMessage(boolean b) { return this; }
    public void buildAndThrow() { }
    public AssertionFailedError build() { return new AssertionFailedError("shadowed"); }
}

package org.opentest4j;

public class AssertionFailedError extends AssertionError {
    public AssertionFailedError() { }
    public AssertionFailedError(String m) { super(m); }
    public AssertionFailedError(String m, Object e, Object a) { super(m); }
    public AssertionFailedError(String m, Throwable c) { super(m, c); }
    public AssertionFailedError(String m, Object e, Object a, Throwable c) { super(m, c); }
    public boolean isExpectedDefined() { return false; }
    public boolean isActualDefined() { return false; }
    public ValueWrapper getExpected() { return null; }
    public ValueWrapper getActual() { return null; }
}

package org.opentest4j;

public final class ValueWrapper implements java.io.Serializable {
    public static ValueWrapper create(Object v) { return new ValueWrapper(); }
    public static ValueWrapper create(Object v, String s) { return new ValueWrapper(); }
    public java.io.Serializable getValue() { return null; }
    public Class<?> getType() { return null; }
    public String getStringRepresentation() { return ""; }
    public int getIdentityHashCode() { return 0; }
    public Object getEphemeralValue() { return null; }
}

